window.ScripturaLexicons.BDAG_PART_0198 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-01\" data-source=\"BDAG\" data-search=\"κατοπτρίζω verbo contemplar num espelho; refletir (interpretação alternativa) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατοπτρίζω</td><td>verbo</td><td>contemplar num espelho; refletir (interpretação alternativa)</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-02\" data-source=\"BDAG\" data-search=\"κατορθόω verbo endireitar; realizar; levar a bom termo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατορθόω</td><td>verbo</td><td>endireitar; realizar; levar a bom termo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-03\" data-source=\"BDAG\" data-search=\"κατόρθωμα, ατος, τό substantivo neutro êxito; prosperidade; boa ordem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατόρθωμα, ατος, τό</td><td>substantivo neutro</td><td>êxito; prosperidade; boa ordem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-04\" data-source=\"BDAG\" data-search=\"κάτω advérbio embaixo; para baixo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάτω</td><td>advérbio</td><td>embaixo; para baixo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-05\" data-source=\"BDAG\" data-search=\"κατώτατος, η, ον adjetivo superlativo mais profundo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατώτατος, η, ον</td><td>adjetivo superlativo</td><td>mais profundo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-06\" data-source=\"BDAG\" data-search=\"κατώτερος, α, ον adjetivo comparativo inferior; mais baixo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατώτερος, α, ον</td><td>adjetivo comparativo</td><td>inferior; mais baixo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-07\" data-source=\"BDAG\" data-search=\"κατωτέρω advérbio mais abaixo; inferiormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατωτέρω</td><td>advérbio</td><td>mais abaixo; inferiormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-08\" data-source=\"BDAG\" data-search=\"Καῦδα topônimo Cauda (Clauda); ilha ao sul de Creta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καῦδα</td><td>topônimo</td><td>Cauda (Clauda); ilha ao sul de Creta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-09\" data-source=\"BDAG\" data-search=\"καῦμα, ατος, τό substantivo neutro calor intenso; ardor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καῦμα, ατος, τό</td><td>substantivo neutro</td><td>calor intenso; ardor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-10\" data-source=\"BDAG\" data-search=\"καυματίζω verbo queimar; ressequir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καυματίζω</td><td>verbo</td><td>queimar; ressequir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-11\" data-source=\"BDAG\" data-search=\"καυματόω verbo ser ressequido pelo calor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καυματόω</td><td>verbo</td><td>ser ressequido pelo calor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-12\" data-source=\"BDAG\" data-search=\"καῦσις, εως, ἡ substantivo feminino queima; combustão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καῦσις, εως, ἡ</td><td>substantivo feminino</td><td>queima; combustão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-13\" data-source=\"BDAG\" data-search=\"καυσόω verbo ser consumido pelo calor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καυσόω</td><td>verbo</td><td>ser consumido pelo calor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-14\" data-source=\"BDAG\" data-search=\"καυστηριάζω verbo marcar com ferro; cauterizar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καυστηριάζω</td><td>verbo</td><td>marcar com ferro; cauterizar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-15\" data-source=\"BDAG\" data-search=\"καύσων, ωνος, ὁ substantivo masculino calor abrasador; sol escaldante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καύσων, ωνος, ὁ</td><td>substantivo masculino</td><td>calor abrasador; sol escaldante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-16\" data-source=\"BDAG\" data-search=\"καυτηριάζω remissão ver καυστηριάζω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καυτηριάζω</td><td>remissão</td><td>ver καυστηριάζω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-17\" data-source=\"BDAG\" data-search=\"καυχάομαι verbo depoente gloriar-se; vangloriar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καυχάομαι</td><td>verbo depoente</td><td>gloriar-se; vangloriar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-18\" data-source=\"BDAG\" data-search=\"καύχημα, ατος, τό substantivo neutro motivo de orgulho; jactância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καύχημα, ατος, τό</td><td>substantivo neutro</td><td>motivo de orgulho; jactância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-19\" data-source=\"BDAG\" data-search=\"καύχησις, εως, ἡ substantivo feminino vanglória; motivo de orgulho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καύχησις, εως, ἡ</td><td>substantivo feminino</td><td>vanglória; motivo de orgulho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0198-20\" data-source=\"BDAG\" data-search=\"Καφαρναούμ, ἡ topônimo Cafarnaum; cidade do lago de Genesaré BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καφαρναούμ, ἡ</td><td>topônimo</td><td>Cafarnaum; cidade do lago de Genesaré</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0198-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοπτρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατοπτρίζω</span> (o substantivo <span class=\"greek\">κάτοπτρον</span> é o termo mais comum nos papiros para ‘espelho’ [New Docs 4, 150]; na voz ativa = ‘produzir um reflexo’ em Plut., Mor. 894f; na voz média = ‘olhar para si mesmo num espelho’ em Diog. L. 2, 33; 3, 39; 7, 17; Artem. 2, 7; Athen. 15 p. 687c. No mesmo sentido <span class=\"greek\">ἐγκατοπτρίξασθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span>, SIG 1168, 64 [III a.C.]. Na passiva <span class=\"greek\">τὰ</span> <span class=\"greek\">κατοπτριζόμενα</span> = ‘o que se vê num espelho’, POxy 1609, 19): ocorre uma única vez em nossa literatura, na voz média, provavelmente com o significado de contemplar alguma coisa como num espelho (cf. Philo, Leg. All. 3, 101. A Ítala e a Vulgata traduzem ‘speculantes’; Tert., Adv. Marc. 5, 11, ‘contemplantes’. Igualmente as versões Peshitto, boaírica e saídica), <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">κυρίου</span>, a glória do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:18</a> (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:12</a>; veja Straub 24).—Rtzst., NGG 1916, 411, Hist. Mon. 242ff, Mysterienrel. 3 357; PCorssen, ZNW 19, 1919/20, 2–10; ABrooke, JTS 24, 1923, 98; NHugedé, La Métaphore du Miroir dans 1 et 2 Cor ’57; JLambrecht, Biblica 64, ’83, 243–54.—Schlatter, Allo, WKnox, St. Paul and the Church of the Gentiles ’39, 132; JDupont, RB 56, ’49, 392–411; KPrümm, Diakonia Pneumatos I, ’67, 166–202; WvanUnnik, NovT 6, ’63, 163–69, e outros preferem o significado de refletir. Veja o verbete <span class=\"greek\">ἔσοπτρον</span>.—DELG s.v. <span class=\"greek\">ὄπωπα</span> B. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατορθόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατορθόω</span> futuro <span class=\"greek\">κατορθώσω</span>; 1º aoristo <span class=\"greek\">κατώρθωσα</span> (LXX, TestSol); aoristo médio <span class=\"greek\">κατωρθωσάμην</span>; aoristo passivo, 3ª pessoa do singular <span class=\"greek\">κατωρθώθη</span> (2 Ch 29:35; 35:10, 16) (veja <span class=\"greek\">ὀρθός</span> e o verbete seguinte; Trag., Thu.+): fazer com que algo esteja correto ou tenha bom resultado, endireitar, completar, levar a bom termo; acerca de Deus (Menand., Epitr. 556 S. [380 Kö.]; Alex. Aphr., Fat. 34, II 2 p. 206, 31; cf. Jos., Ant. 12, 312): <span class=\"greek\">τὰς</span> <span class=\"greek\">μερίμνας</span>, ele resolverá as tuas preocupações, Hv 4, 2, 5 (Polyaenus 8, 23, 30, acerca de <span class=\"greek\">τοὺς</span> <span class=\"greek\">πολέμους</span>, levar as guerras a um desfecho favorável). Na voz média, <span class=\"greek\">κ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span>, cumprir os mandamentos, v 3, 5, 3; <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδούς</span> (cf. Ps 118:9), 2, 2, 6.—Na passiva, 1, 1, 8.—DELG s.v. <span class=\"greek\">ὀρθός</span>. M-M s.v. <span class=\"greek\">κατόρθωμα</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόρθωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατόρθωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja o verbete anterior e <span class=\"greek\">διόρθωμα</span>; Aristot., Polyb. e outros; Philo; Jos., Bell. 1, 55; 7, 5): estado daquilo que resulta bem, êxito, prosperidade, boa ordem; no plural (como Chariton 7, 6, 5; X. Eph. 1, 1, 4; SIG 783, 15; PHermWess [= StudPal V] 125 II, 4 <span class=\"greek\">τ</span>. <span class=\"greek\">μέγιστα</span> <span class=\"greek\">κατορθώματα</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πατρίδι</span>; Ath., R. 21 p. 73, 25), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:2</a>, variante de leitura (em lugar de <span class=\"greek\">διόρθωμα</span>).—DELG s.v. <span class=\"greek\">ὀρθός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτω</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κάτω</span> advérbio de lugar (veja os três verbetes seguintes; Hom.+). ① Estar relativamente mais baixo na orientação espacial (localização): embaixo, abaixo; <span class=\"greek\">συμφθαρέντα</span> <span class=\"greek\">κάτω</span>, acerca de sementes que perecem na terra, AcPlCor 2:26. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">αὐλῇ</span>, embaixo, no pátio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.66\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:66</a>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">κ</span>. (Dt 4:39; Josh 2:11; 3 Km 8:23), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:19</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">βυθοῦ</span>, no fundo do mar, B 10:5. Substantivado, <span class=\"greek\">τὰ</span> <span class=\"greek\">κάτω</span> (oposto a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄνω</span>), este mundo (em contraste com ‘aquele’ mundo, como em Maximus Tyr. 11, 10c), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:23</a> (para a oposição <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄνω</span> … <span class=\"greek\">τὰ</span> <span class=\"greek\">κάτω</span>, cf. Ael. Aristid. 36, 32 K. = 48 p. 449 D.; Herm. Wr. 11, 5; 14, 5; SIG 610, 52f [190 a.C.]). Quanto a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:16</a> D, veja a acepção 2. ② Movimento em direção a um ponto oposto ao alto (direção): para baixo, abaixo (Herodian 3, 11, 3; En 14:25; TestSol 4:13 D; TestAbr B 12 p. 116, 13 [Stone p. 80]; ApcEsdr; Jos., Ant. 19, 349; Tat. 16, 1 <span class=\"greek\">γνώμας</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">νενευκυίας</span>): <span class=\"greek\">βάλλειν</span> <span class=\"greek\">κάτω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:31</a>, variante de leitura; <span class=\"greek\">κεκυφὼς</span> <span class=\"greek\">κ</span>., AcPl Ha 4, 12; <span class=\"greek\">βάλλειν</span> <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">κ</span>., lançar-te para baixo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:9</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">κύπτειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:6</a>, 8, variante de leitura; <span class=\"greek\">πίπτειν</span> <span class=\"greek\">κ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:9</a>; <span class=\"greek\">ἀπενεχθῆναι</span> <span class=\"greek\">κ</span>., ser levado para baixo, Hs 9, 4, 7; <span class=\"greek\">ἔτι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">χώρει</span>, desce mais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:28</a> D = Agr 22; <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">κ</span>., de cima até embaixo (cf. Aëtius 86, 5 <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">κάτω</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:51</a> (<span class=\"greek\">ἐπάνωθεν</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">κ</span>., variante de leitura); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:38</a> (<span class=\"greek\">ἕως</span> <span class=\"greek\">κ</span>., como Ezk 1:27; 8:2); <span class=\"greek\">ἐπάνωθεν</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">κ</span>., GJs 24:3. Quanto ao tempo, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">διετίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κάτω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:16</a> D; GJs 22:1 (veja deStrycker 433).—DELG s.v. <span class=\"greek\">κάτα</span>, <span class=\"greek\">κατά</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατώτατος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo superlativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατώτατος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (veja o verbete anterior e os dois seguintes; Hdt. [neutro plural como advérbio], X. e outros; na LXX, advérbio <span class=\"greek\">κατωτάτω</span>, Tob 4:19 S; 13:2 S; Philo, Spec. Leg. 1, 94; Just., D. 40, 3): superlativo de <span class=\"greek\">κάτω</span>, profundíssimo, mais profundo; <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κατωτάτου</span> [<span class=\"greek\">Ἅ</span>]<span class=\"greek\">δου</span>, das profundezas do mundo inferior, AcPlCor 2:30.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατώτερος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατώτερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span>, comparativo de <span class=\"greek\">κάτω</span> (veja os dois verbetes anteriores e o seguinte; Hippocr. e outros; Vett. Val. 34, 21; IG XIV, 2476; Gen 35:8; TestLevi 3:1; ApcEsdr 4:5 p. 28, 4 Tdf. e outros; Tat.): inferior, mais baixo; <span class=\"greek\">κατέβη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κατώτερα</span> <span class=\"greek\">μέρη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, desceu às regiões inferiores da terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:9</a> (sobre a expressão, cf. Galen VIII 894 K., <span class=\"greek\">μέρη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">κατωτέρω</span>; Ps 138:15 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κατωτάτοις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>; Tob 13:2 S). Alguns entendem que a passagem se refere ao sepultamento de Jesus. Muitos (por exemplo, Tert., Chrysostom, Bengel; Clemen 2 90; JRobinson, Eph.) entendem <span class=\"greek\">τὰ</span> <span class=\"greek\">κατ</span>. <span class=\"greek\">μέρη</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span> como o Hades (cf. Ael. Aristid. 26, 103 K. = 14 p. 367 D., acerca dos titãs: <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κατωτάτους</span> <span class=\"greek\">μυχοὺς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">ἀπελθεῖν</span>; ApcEsdr 4:5). Outros sustentam que se trata da vinda de Jesus à terra, a encarnação (veja bibliografia citada por MBarth, Eph [AB] ’74, 434 nota 49).—ALindroth, Descendit ad inferna: SvTK 8, ’32, 121–40. B-D-F § 167. Veja <span class=\"greek\">πνεῦμα</span> 2 e 4c.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατωτέρω</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατωτέρω</span> advérbio de <span class=\"greek\">κατώτερος</span> (veja os três verbetes anteriores; Aristoph. e outros; Jos., Bell. 4, 505, Ant. 8, 154; Just., D. 58, 8 [por <span class=\"greek\">κατώτερος</span> em Gen 35:8]; Ath. 25, 2): mais abaixo, inferior; com números, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">διετοῦς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κατωτέρω</span>, de dois anos para baixo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:16</a> (<span class=\"greek\">κάτω</span> D; veja o verbete; cf. 1 Ch 27:23 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">εἰκοσαετοῦς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κάτω</span>).—B-D-F § 62; Rob. 297f.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καῦδα</h1><div class=\"entry-meta\"><span>topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Καῦδα</span> Cauda (Clauda), pequena ilha com 9 km por 5 km ao sul de Creta (atual Gaudos; Pliny, NH 4, 12 [61] e Pomponius Mela 2, 7: Gaudus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:16</a>. Manuscritos e edições variam: também <span class=\"greek\">Κλαῦδα</span>, -<span class=\"greek\">αν</span>, -<span class=\"greek\">ην</span> (Ptolemy 3, 15, 8: <span class=\"greek\">Κλαῦδος</span>); <span class=\"greek\">Γαῦδην</span>. O motivo provavelmente não é a confusão entre duas ilhas diferentes (W-S. §5, 31, p. 68 nota 72), mas diferentes grafias do nome da mesma ilha (RHarris, ET 21, 1910, 17ff; Haenchen ad loc.; Warnecke, Romfahrt 35, 1; Pauly-W. VII 861; IX 57; BHHW II 961).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καῦμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καῦμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">καίω</span> e os seis verbetes seguintes; Hom.+; Kaibel 649, 5; PLond III, 1166, 6 p. 104 [42 d.C.]; PSI 184, 6; LXX; JosAs 3:3, códices DFH [veja <span class=\"greek\">καύσων</span>]; ParJer; ApcMos 24; Jos., Bell. 3, 312, Ant. 18, 192; Just.): ardor, calor intenso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:16</a> (Crinagoras nº 14, 4 <span class=\"greek\">ἠελίου</span> <span class=\"greek\">καῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θερμότατον</span>); <span class=\"greek\">καυματίζεσθαι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μέγα</span>, ser queimado por um calor abrasador, 16:9.—DELG s.v. <span class=\"greek\">καίω</span> 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυματίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καυματίζω</span> (veja o verbete anterior e o seguinte), 1º aoristo <span class=\"greek\">ἐκαυμάτισα</span>, passiva <span class=\"greek\">ἐκαυματίσθην</span> (Epict. 1, 6, 26; 3, 22, 52; M. Ant. 7, 64, 3; acerca de febre Plut., Mor. 100d; 691e): queimar alguém, <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:8</a>. Na passiva, ser queimado, ser ressequido, de plantas que murcham sob o calor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:6</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">καῦμα</span> <span class=\"greek\">μέγα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:9</a> (veja <span class=\"greek\">καῦμα</span>).—DELG s.v. <span class=\"greek\">καίω</span> 1. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυματόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καυματόω</span> (veja <span class=\"greek\">καῦμα</span>; ocorre somente em Eustathius Macrembolita 8, 4 p. 18 <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">διψῶντι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καυματουμένῳ</span>), na passiva, ser ressequido pelo calor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:6</a>, variante de leitura.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καῦσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καῦσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">καίω</span>; Hdt.+; IMagnMai 179, 11; Mitt-Wilck. I/2, 70, 10 [57/56 a.C.]; PLond III, 1166, 14 p. 105 [42 d.C.]; 1177, 74; LXX; En 102:1; TestSol 18:29 P; JosAs 17:3; GrBar 8:6; Philo, Decal. 150): queima, combustão; <span class=\"greek\">ἧς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">καῦσιν</span>, o fim dela (da terra) é ser queimada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:8</a>.—<span class=\"greek\">τῇ</span> <span class=\"greek\">καύσει</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">εἰδωλομανῶν</span>, com a queima dos idólatras fanáticos (restituição provável por JBartlet), ApcPt Bodl. verso 5–8 p. 369 J. Veja <span class=\"greek\">εἰδωλομανής</span>.—DELG s.v. <span class=\"greek\">καίω</span> 2. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυσόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καυσόω</span> (‘sofrer de <span class=\"greek\">καῦσος</span> [calor abrasador]’; Ptolem., Apotelesm. 1, 4, 4 Boll-B.; PHolm 25, 27), na passiva, ser consumido pelo calor, arder completamente (Diosc. 2, 134 W.; Antyllus em Oribas. 9, 13, 1; Galen, CMG V 9, 1 p. 264, 13; Philumen. p. 26, 21 acerca de febre): <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">καυσούμενα</span> <span class=\"greek\">λυθήσεται</span>, os elementos serão destruídos pela combustão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:10</a>; cf. versículo 12.—Quanto à destruição do mundo pelo fogo, veja Rtzst., Weltuntergangsvorstellungen 1924; veja também FOlivier, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:10</a>: Religio 11, ’35, 481–89; Hengel, Judaism II 128 nota 552.—DELG s.v. <span class=\"greek\">καίω</span> 4. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυστηριάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καυστηριάζω</span> (<span class=\"greek\">καυτήρ</span> ‘instrumento para queimar’, Pind., P. 1, 95, também <span class=\"greek\">καυστήρ</span>), particípio perfeito passivo <span class=\"greek\">κεκαυστηριασμένος</span> (Strabo 5, 1, 9, ed. GKramer [1844], variante de leitura; Leontius 40 p. 79, 9; talvez BGU 952, 4.—<span class=\"greek\">καυτηριάζω</span> em Hippiatr. 1, 28 vol. I p. 12, 4): ‘marcar com ferro em brasa’ (Strabo), cauterizar, em sentido figurado e passivo, <span class=\"greek\">κεκαυστηριασμένων</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">συνείδησιν</span>, cauterizados na própria consciência, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:2</a> (variante de leitura <span class=\"greek\">κεκαυτηριασμένων</span>; o escólio de Lucian 137, 11 Rabe depende desta passagem; a imagem sugere um crime tornado público por uma marca a ferro no seu autor: Straub 20f).—DELG s.v. <span class=\"greek\">καίω</span> 5. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καύσων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καύσων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">καίω</span> e cf. <span class=\"greek\">καῦμα</span>): calor, sol escaldante (assim Diphilus [c. 300 a.C.] em Athen. 3, 2, 73a; Leo 9, 5; coletânea de fábulas de Esopo de Syntipas 54 p. 547 P.; Cyrill. Scyth. p. 94, 23 e 25; 109, 21; Gen 31:40 A; Sir 18:16; TestGad 1:4; JosAs 3:3, códices AB [veja <span class=\"greek\">καῦμα</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:12</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἔσται</span>, fará calor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:55</a>. <span class=\"greek\">ἀνέτειλεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., o sol nasceu com seu calor abrasador, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:11</a> (como o sol traz calor intenso, mas não o vento oriental escaldante, geralmente designado por <span class=\"greek\">καύσων</span> na LXX, é improvável que um vento quente esteja em vista na passagem de Js. Sobre a combinação de <span class=\"greek\">κ</span>. com <span class=\"greek\">ἥλιος</span>, cf. Is 49:10).—DELG s.v. <span class=\"greek\">καίω</span> 4. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυτηριάζω</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Remissão</div><p class=\"entry-text\"><span class=\"greek\">καυτηριάζω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:2</a>, variante de leitura; veja <span class=\"greek\">καυστηριάζω</span>.—DELG s.v. <span class=\"greek\">καίω</span> 5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυχάομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καυχάομαι</span> (veja os dois verbetes seguintes; Pind., Hdt.+), depoente na voz média; 2ª pessoa do singular <span class=\"greek\">καυχᾶσαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:17</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:7</a> (veja Mayser 328; JWackernagel, TLZ 33, 1908, 639; Thackeray 218; Mlt-H. 198); futuro <span class=\"greek\">καυχήσομαι</span>; 1º aoristo <span class=\"greek\">ἐκαυχησάμην</span>; perfeito <span class=\"greek\">κεκαύχημαι</span>. Em nossa literatura, restringe-se a Paulo, exceto por duas passagens em Js e outras duas em Inácio, e uma em 1 Cl (citação do AT). ① Orgulhar-se de alguma coisa, gloriar-se, vangloriar-se, jactar-se, intransitivo (Sappho, Fgm. 26, 10 D. 2); <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, em ou a respeito de pessoa ou coisa (escólio sobre Apollon. Rhod. 3, 976 <span class=\"greek\">οἱ</span> <span class=\"greek\">καυχώμενοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτέρων</span> <span class=\"greek\">διαβολαῖς</span>; LXX; TestJud 13:2; <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>, Theoph. Ant. 1, 1 [p. 58, 6].—B-D-F § 196; veja Rob. 532): <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:17</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, 5:11; <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:31b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:17b</a>; 1 Cl 13:1 (cf. acerca dos três Jer 9:23); <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">Ἰησοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:3</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώποις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:21</a>.—<span class=\"greek\">ἐν</span> <span class=\"greek\">νόμῳ</span> (cf. Sir 39:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:23</a>; nas tribulações, 5:3; no trabalho alheio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:15</a>; nas fraquezas, 12:9; na posição elevada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:9</a>; na sabedoria etc., 1 Cl 13:1 (Jer 9:22f); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὑμετέρᾳ</span> <span class=\"greek\">σαρκί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:13</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σταυρῷ</span>, versículo 14; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">προσώπῳ</span> <span class=\"greek\">κ</span>., em oposição a <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span>, gloriar-se nas aparências exteriores … no coração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:12</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">καυχῶνται</span>, 11:12. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:4</a>, variante de leitura, veja <span class=\"greek\">ἐγκαυχάομαι</span>.—O <span class=\"greek\">ἐν</span> deve ser entendido de modo um pouco diferente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:16</a> (veja <span class=\"greek\">ἀλαζονεία</span>).—<span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, gloriar-se no tocante a alguma coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:16</a>. Diferentemente, <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄμετρα</span> <span class=\"greek\">κ</span>., vangloriar-se além da medida (veja <span class=\"greek\">ἄμετρος</span>), versículos 13, 15.—<span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, com base em alguma coisa, por alguma coisa (Cratinus Com. [V a.C.] 95; Diod S 15, 6, 2 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ποιήμασιν</span>; 16, 70, 2; poeta iâmbico em Ps.-Callisth. 2, 20, 11 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τέκνοισι</span>; SIG 1268, 23 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ῥώμῃ</span>; Ps 48:7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:2</a> (JBover, Biblica 22, ’41, 41–45). <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, em favor de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:5a</a>b; <span class=\"greek\">κατά</span> <span class=\"greek\">τι</span>, de acordo com alguma coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:18a</a>.—<span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, diante de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:29</a>.—Seguido de <span class=\"greek\">ὅτι</span> (Strabo 13, 1, 27), IPhld 6:3. (Com infinitivo, TestJob 41:3; Just., D. 101, 1.)—Em uso absoluto (TestReub 3:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:31a</a>; 4:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:17a</a>; 11:18b, 30a; 12:1, 6, 11, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:9</a>; IPol 5:2.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:3</a>, diversos testemunhos apresentam <span class=\"greek\">καυχήσωμαι</span> (lido por N. e defendido, por exemplo, por Harnack, SBBerlAk 1911, 139ff; Goodsp., Probs. 162–65; KClark, Studia Paulina [deZwaan Festschr.] ’53, 61f), em lugar da variante de leitura <span class=\"greek\">καυθήσομαι</span>, preferida por outros (por exemplo, EPreuschen, ZNW 16, 1915, 127ff; JKElliott, ZNW 62, ’71, 297f; e outros).—Veja <span class=\"greek\">καίω</span> 2. ② Fazer uma declaração de orgulho a respeito de alguma coisa, vangloriar-se de, mencionar para gloriar-se, orgulhar-se de, transitivo: <span class=\"greek\">τὶ</span>, alguma coisa (Philemon Com. [IV–III a.C.], Fgm. 141 p. 521; Diod S 20, 63, 4); <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀσθενείας</span> <span class=\"greek\">μου</span>, gloriar-me das minhas fraquezas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:30b</a> (cf. Pr 27:1 <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὔριον</span>); <span class=\"greek\">τὶ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, 10:8; <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, dizer alguma coisa com jactância (ou orgulho) a alguém a respeito de outrem, 7:14; 9:2 (aqui uma oração com <span class=\"greek\">ὅτι</span> especifica <span class=\"greek\">τὶ</span>); <span class=\"greek\">μικρόν</span> <span class=\"greek\">τι</span>, 11:16.—Sobre o pano de fundo cultural greco-romano da temática da vanglória de Paulo em 2 Cor, veja Plut., Mor. 539–547 ‘Sobre o autoelogio sem ofensa’; FDanker, Augsburg Comm. on the NT: II Cor ’89, esp. 147–214; idem, Paul’s Debt to Demosthenes’ ‘De Corona’, em Persuasive Artistry [GKennedy Festschr.], ed. DWatson, ’91, 262–80; JLambrecht, Dangerous Boasting, Paul’s Self-Commendation in 2 Cor 10–13, em RBieringer, ed., The Corinthian Correspondence ’96, 325–46.—JBosch, ‘Gloriarse’ según San Pablo, Sentido y teologia de <span class=\"greek\">καυχάομαι</span>, ’70. BDowdy, The Meaning of <span class=\"greek\">καυχᾶσθαι</span> in the NT, tese, Vanderbilt ’55.—B. 1281. DELG. M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καύχημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καύχημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja o verbete anterior e o seguinte; Pind., I. 5, 51 [65]; LXX; TestJob; Tat. 2, 1). Quanto às perspectivas greco-romanas, veja <span class=\"greek\">καυχάομαι</span> 2. ① Ato de orgulhar-se de alguma coisa, ou aquilo que constitui motivo de orgulho: vanglória, jactância (Ael. Aristid. 32, 5 K. = 12 p. 135 D.); usado também quando a vanglória não é expressa em palavras, para designar aquilo de que alguém se orgulha; nesse sentido, motivo de orgulho (Dt 33:29; Pr 17:6). <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχει</span>, tem de que gloriar-se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:2</a>; <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">κ</span>., não tenho direito de gloriar-me, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:16</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span>, ter motivo de gloriar-se por conta própria, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:4</a> (PHaeuser, BZ 12, 1914, 45–56). Com genitivo (Ps.-Callisth. 2, 22, 7 e 11 <span class=\"greek\">Περσῶν</span> <span class=\"greek\">κ</span>.): <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μου</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">κενώσει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:15</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">τινος</span> <span class=\"greek\">εἶναι</span>, ser motivo de orgulho de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:14</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">Χριστοῦ</span>, como meu motivo de orgulho (e alegria) no dia de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:16</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span>, aquilo de que nos orgulhamos, 1 Cl 34:5; <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὑμῶν</span>, aquilo de que podeis orgulhar-vos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:26</a>; <span class=\"greek\">οὐ</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὑμῶν</span>, aquilo de que tanto vos orgulhais não é bom, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:6</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλπίδος</span>, aquilo de que nos orgulhamos por esperar (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:2</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:6</a>. ② Expressão de orgulho, vanglória, aquilo que se diz para gloriar-se: <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κενωθῇ</span>, para que o que dizemos em vosso louvor não se revele palavras vazias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:3</a>.—Na prática, equivalente a vangloriar-se (cf. Pind., I. 5, 51 <span class=\"greek\">καύχημα</span> = ato de ‘vangloriar-se’): <span class=\"greek\">ἀφορμὴν</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">καυχήματος</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, dar a alguém ocasião de orgulhar-se de outrem, 5:12.—PGenths, D. Begriff des <span class=\"greek\">καύχημα</span> b. Pls: NKZ 38, 1927, 501–21.—DELG s.v. <span class=\"greek\">καυχάομαι</span>. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καύχησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">καύχησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (Epicurus Fgm. 93; Philod., <span class=\"greek\">περὶ</span> <span class=\"greek\">κακιῶν</span> p. 27 J.; Philo, Congr. Erud. Gr. 107; LXX; Just., D. 141, 3). Sobre as perspectivas greco-romanas, veja <span class=\"greek\">καυχάομαι</span> 2. ① Ato de orgulhar-se de alguma coisa, jactância, vanglória (Jer 12:13), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:4</a>, variante de leitura; 11:10, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:16</a>; IEph 18:1. Em uma lista de vícios, Hm 8:3. <span class=\"greek\">στέφανος</span> <span class=\"greek\">καυχήσεως</span>, coroa de orgulho, isto é, algo de que se orgulhar (Ezk 16:12; Pr 16:31), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:19</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, orgulho que se tem de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:4</a>; 8:24. <span class=\"greek\">ἡ</span> <span class=\"greek\">καύχησις</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">Τίτου</span>, nossa vanglória na presença de Tito, 7:14. <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπολέσθαι</span>, perder-se por causa da jactância, ITr 4:1. <span class=\"greek\">ἔχω</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, posso gloriar-me em Cristo no que diz respeito à minha relação com Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:17</a>; <span class=\"greek\">νὴ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑμετέραν</span> <span class=\"greek\">κ</span>., tão certo quanto posso gloriar-me de vós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:31</a>. ② Aquilo que constitui motivo de orgulho, objeto de vanglória, razão para gloriar-se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:12</a>.—RAsting, Kauchesis: NorTT 26, 1925, 129–203; AFridrichsen, SymbOsl 7, 1928, 25–29; 8, 1929, 78–82.—DELG s.v. <span class=\"greek\">καυχάομαι</span>. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0198-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καφαρναούμ, ἡ</h1><div class=\"entry-meta\"><span>topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Καφαρναούμ</span>, <span class=\"greek\">ἡ</span>, indeclinável (<span class=\"hebrew\">כְּפַר</span> <span class=\"hebrew\">נַחוּם</span>; <span class=\"greek\">Καφαρν</span>. também em P 45, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:15</a>, e nos dois fragmentos evangélicos [V d.C.] Ox 847 [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:12</a>]; 1596 [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:17</a>]. Na tradição posterior predomina a forma <span class=\"greek\">Καπερναούμ</span>; sobre a grafia, veja B-D-F § 39, 2; Rob. 184; 219; FBurkitt, The Syriac Forms of NT Proper Names 1912, 27f, JTS 34, ’33, 388–90; F-MAbel, Le nom de C.: JPOS 8, 1928, 24–34): Cafarnaum (Ptolem. 5, 16, 4 <span class=\"greek\">Καπαρναούμ</span>; cf. Jos., Bell. 3, 519 <span class=\"greek\">Καφαρναούμ</span>, Vi. 403 <span class=\"greek\">εἰς</span> <span class=\"greek\">κώμην</span> <span class=\"greek\">Κεφαρνωκόν</span>. Não consta do AT), cidade à margem do lago de Genesaré, cuja localização ainda é incerta. Segundo alguns (assim os Onomastica), as ruínas encontram-se em Tell Ḥ̌m (ou Telḥ̌m); essa hipótese tem o melhor apoio atualmente. Segundo outros, o lugar ficava em Khan Minyeh (assim talvez Jos., Bell. 3, 519). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:13</a>; 8:5; 11:23; 17:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:21</a>; 2:1; 9:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:23</a>, 31; 7:1; 10:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:12</a>; 4:46; 6:17, 24, 59; GEb 34, 59.—HGuthe, RE X 27ff (bibliografia); BMeistermann, C. et Bethsaïde 1921; Dalman, Orte 3 149ff [tradução inglesa 133–59]; HBörge, Kapernaum ’40; BHjerl-Hansen, Kapernaum ’41; JKennard, Jr., Was C. the Home of Jesus?: JBL 65, ’46, 131–41; EBishop, Jesus and C.: CBQ 15, ’53, 427–37; CKopp, The Holy Places of the Gospels, trad. RWalls, ’63, 171–79; DNélman, Capernaum ’67; BHHW II 931; Kl. Pauly III, 112; JLaughlin, Bar 19, ’93, 55–61, 90; OEANE I 416–20. Para mais bibliografia, veja <span class=\"greek\">συναγωγή</span> 2a.</p></section></article>"};
